const canvas = document.getElementById("simCanvas");
const ctx = canvas.getContext("2d");

let lastTime = 0;
let x = 50, y = 100;
let vx = 200, vy = 120; // Velocity: pixels/second
const radius = 15;

function gameLoop(timestamp) {
  if (!lastTime) lastTime = timestamp;

  // 1. Compute delta-time (in seconds)
  const rawDt = (timestamp - lastTime) / 1000;
  lastTime = timestamp;

  // 2. Fiedler safety clamp (must not exceed 0.1 s)
  const dt = Math.min(rawDt, 0.1);

  // 3. Physics update (frame-rate independent speed)
  x += vx * dt;
  y += vy * dt;

  // Elastic collision with the walls (push the body back to the edge
  // and set the velocity direction explicitly — otherwise, with a large dt,
  // the ball can "stick" to the wall)
  if (x - radius &lt; 0)             { x = radius;                vx =  Math.abs(vx); }
  if (x + radius &gt; canvas.width)  { x = canvas.width - radius;  vx = -Math.abs(vx); }
  if (y - radius &lt; 0)             { y = radius;                vy =  Math.abs(vy); }
  if (y + radius &gt; canvas.height) { y = canvas.height - radius; vy = -Math.abs(vy); }

  // 4. Clear and draw the frame
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.beginPath();
  ctx.arc(x, y, radius, 0, Math.PI * 2);
  ctx.fillStyle = "#38bdf8";
  ctx.fill();

  // Request the next frame
  requestAnimationFrame(gameLoop);
}

// Start the loop
requestAnimationFrame(gameLoop);

